-- ==========================================================
-- TRATTORIAS RESTAURANT - COMPLETE SUPABASE SETUP & SEED DATA
-- Copy ALL lines and RUN in Supabase Dashboard -> SQL Editor
-- ==========================================================

-- 1. Create Categories Table
CREATE TABLE IF NOT EXISTS public.categories (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    subtitle TEXT DEFAULT '',
    icon TEXT DEFAULT 'layout-grid',
    display_order INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Ensure subtitle column exists
ALTER TABLE public.categories ADD COLUMN IF NOT EXISTS subtitle TEXT DEFAULT '';

-- 2. Create Menu Items Table
CREATE TABLE IF NOT EXISTS public.menu_items (
    id TEXT PRIMARY KEY,
    "categoryId" TEXT REFERENCES public.categories(id) ON DELETE SET NULL,
    "categoryName" TEXT,
    name TEXT NOT NULL,
    description TEXT,
    price TEXT,
    variants JSONB DEFAULT '[]'::jsonb,
    is_available BOOLEAN DEFAULT true,
    image_url TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. Create Restaurant Settings Table
CREATE TABLE IF NOT EXISTS public.restaurant_settings (
    id TEXT PRIMARY KEY,
    settings JSONB NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 4. Grant Table Permissions to Supabase Roles (Fixes "permission denied")
GRANT USAGE ON SCHEMA public TO anon, authenticated, service_role;
GRANT ALL ON ALL TABLES IN SCHEMA public TO anon, authenticated, service_role;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO anon, authenticated, service_role;
GRANT ALL ON ALL ROUTINES IN SCHEMA public TO anon, authenticated, service_role;

ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON TABLES TO anon, authenticated, service_role;

-- 5. Enable Row Level Security (RLS)
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.menu_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.restaurant_settings ENABLE ROW LEVEL SECURITY;

-- 6. Drop existing policies to prevent conflicts or vulnerabilities
DROP POLICY IF EXISTS "Allow public read categories" ON public.categories;
DROP POLICY IF EXISTS "Allow public read menu_items" ON public.menu_items;
DROP POLICY IF EXISTS "Allow public read settings" ON public.restaurant_settings;
DROP POLICY IF EXISTS "Allow all operations categories" ON public.categories;
DROP POLICY IF EXISTS "Allow all operations items" ON public.menu_items;
DROP POLICY IF EXISTS "Allow all operations settings" ON public.restaurant_settings;
DROP POLICY IF EXISTS "Allow authenticated insert categories" ON public.categories;
DROP POLICY IF EXISTS "Allow authenticated update categories" ON public.categories;
DROP POLICY IF EXISTS "Allow authenticated delete categories" ON public.categories;
DROP POLICY IF EXISTS "Allow authenticated insert menu_items" ON public.menu_items;
DROP POLICY IF EXISTS "Allow authenticated update menu_items" ON public.menu_items;
DROP POLICY IF EXISTS "Allow authenticated delete menu_items" ON public.menu_items;
DROP POLICY IF EXISTS "Allow authenticated insert settings" ON public.restaurant_settings;
DROP POLICY IF EXISTS "Allow authenticated update settings" ON public.restaurant_settings;
DROP POLICY IF EXISTS "Allow authenticated delete settings" ON public.restaurant_settings;

-- 7. Public Read Policies (Anyone can view menu and settings)
CREATE POLICY "Allow public read categories" ON public.categories FOR SELECT TO public USING (true);
CREATE POLICY "Allow public read menu_items" ON public.menu_items FOR SELECT TO public USING (true);
CREATE POLICY "Allow public read settings" ON public.restaurant_settings FOR SELECT TO public USING (true);

-- 8. Authenticated Admin Modification Policies (Only logged-in admin users can modify data)
CREATE POLICY "Allow authenticated insert categories" ON public.categories FOR INSERT TO authenticated WITH CHECK (true);
CREATE POLICY "Allow authenticated update categories" ON public.categories FOR UPDATE TO authenticated USING (true) WITH CHECK (true);
CREATE POLICY "Allow authenticated delete categories" ON public.categories FOR DELETE TO authenticated USING (true);

CREATE POLICY "Allow authenticated insert menu_items" ON public.menu_items FOR INSERT TO authenticated WITH CHECK (true);
CREATE POLICY "Allow authenticated update menu_items" ON public.menu_items FOR UPDATE TO authenticated USING (true) WITH CHECK (true);
CREATE POLICY "Allow authenticated delete menu_items" ON public.menu_items FOR DELETE TO authenticated USING (true);

CREATE POLICY "Allow authenticated insert settings" ON public.restaurant_settings FOR INSERT TO authenticated WITH CHECK (true);
CREATE POLICY "Allow authenticated update settings" ON public.restaurant_settings FOR UPDATE TO authenticated USING (true) WITH CHECK (true);
CREATE POLICY "Allow authenticated delete settings" ON public.restaurant_settings FOR DELETE TO authenticated USING (true);

-- 8. Insert Categories (44 categories)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, subtitle = EXCLUDED.subtitle, icon = EXCLUDED.icon, display_order = EXCLUDED.display_order;

-- 9. Insert Menu Items (350 dishes)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, price = EXCLUDED.price, variants = EXCLUDED.variants, is_available = EXCLUDED.is_available;

-- 10. Insert Settings
ON CONFLICT (id) DO UPDATE SET settings = EXCLUDED.settings;
